package com.example.remoteclient.model

import com.google.gson.annotations.SerializedName

// Represents the server state
enum class RemoteServerState {
    STOPPED, STARTING, RUNNING, STOPPING, ERROR
}

// Represents the server status response
data class ServerStatus(
    @SerializedName("state") val state: RemoteServerState,
    @SerializedName("endpoint") val endpoint: String,
    @SerializedName("sessions") val sessions: List<RemoteSession>
)

// Represents a remote session
data class RemoteSession(
    @SerializedName("id") val id: String,
    @SerializedName("target") val target: RemoteTarget
)

// Represents a remote target (e.g., a window or process)
data class RemoteTarget(
    @SerializedName("hwnd") val hwnd: Int,
    @SerializedName("pid") val pid: Int,
    @SerializedName("window_title") val windowTitle: String,
    @SerializedName("process_name") val processName: String
)

// Represents credentials for authentication
data class RemoteCredentials(
    @SerializedName("username") val username: String,
    @SerializedName("password") val password: String
)

// Represents the handshake response
data class HandshakeResponse(
    @SerializedName("session_id") val sessionId: String
)

package com.example.remoteclient.network

import com.example.remoteclient.model.*
import retrofit2.Call
import retrofit2.http.*

interface ApiService {

    @GET("/status")
    fun getStatus(): Call<ServerStatus>

    @POST("/handshake")
    fun handshake(@Body credentials: RemoteCredentials): Call<HandshakeResponse>

    @POST("/sessions/{id}/close")
    fun closeSession(@Path("id") sessionId: String): Call<Void>
}

package com.example.remoteclient.ui

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.lifecycle.viewmodel.compose.viewModel
import com.example.remoteclient.model.RemoteSession
import com.example.remoteclient.viewmodel.DashboardViewModel

@Composable
fun DashboardScreen(viewModel: DashboardViewModel = viewModel()) {
    val serverState by viewModel.serverState.collectAsState()
    val sessions by viewModel.sessions.collectAsState()

    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.Top,
        horizontalAlignment = Alignment.Start
    ) {
        Text("Server State: ${serverState}", style = MaterialTheme.typography.h6)

        Spacer(modifier = Modifier.height(16.dp))

        Text("Active Sessions:", style = MaterialTheme.typography.h6)

        LazyColumn(modifier = Modifier.fillMaxSize()) {
            items(sessions) { session ->
                SessionItem(session = session, onClose = { viewModel.closeSession(session.id) })
            }
        }
    }
}

@Composable
fun SessionItem(session: RemoteSession, onClose: () -> Unit) {
    Card(modifier = Modifier.fillMaxWidth().padding(8.dp), elevation = 4.dp) {
        Row(
            modifier = Modifier.fillMaxWidth().padding(16.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Column {
                Text("Session ID: ${session.id}")
                Text("Target: ${session.target.windowTitle}")
            }
            Button(onClick = onClose) {
                Text("Close")
            }
        }
    }
}

package com.example.remoteclient.ui

import android.widget.Toast
import androidx.compose.foundation.layout.*
import androidx.compose.material.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.input.PasswordVisualTransformation
import androidx.compose.ui.unit.dp
import androidx.lifecycle.viewmodel.compose.viewModel
import com.example.remoteclient.viewmodel.LoginViewModel

@Composable
fun LoginScreen(viewModel: LoginViewModel = viewModel()) {
    var username by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }

    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        TextField(
            value = username,
            onValueChange = { username = it },
            label = { Text("Username") },
            modifier = Modifier.fillMaxWidth()
        )

        Spacer(modifier = Modifier.height(8.dp))

        TextField(
            value = password,
            onValueChange = { password = it },
            label = { Text("Password") },
            visualTransformation = PasswordVisualTransformation(),
            modifier = Modifier.fillMaxWidth()
        )

        Spacer(modifier = Modifier.height(16.dp))

        Button(onClick = {
            viewModel.login(username, password)
        }, modifier = Modifier.fillMaxWidth()) {
            Text("Connect")
        }

        val loginState = viewModel.loginState.collectAsState()
        when (loginState.value) {
            is LoginViewModel.LoginState.Success -> {
                Toast.makeText(LocalContext.current, "Login Successful", Toast.LENGTH_SHORT).show()
            }
            is LoginViewModel.LoginState.Error -> {
                Toast.makeText(LocalContext.current, "Login Failed", Toast.LENGTH_SHORT).show()
            }
            else -> {}
        }
    }
}

package com.example.remoteclient.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.remoteclient.model.RemoteSession
import com.example.remoteclient.network.ApiService
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory

class DashboardViewModel : ViewModel() {

    private val _serverState = MutableStateFlow("Unknown")
    val serverState: StateFlow<String> = _serverState

    private val _sessions = MutableStateFlow<List<RemoteSession>>(emptyList())
    val sessions: StateFlow<List<RemoteSession>> = _sessions

    private val apiService: ApiService by lazy {
        Retrofit.Builder()
            .baseUrl("http://127.0.0.1:8765")
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(ApiService::class.java)
    }

    init {
        fetchServerState()
        fetchSessions()
    }

    private fun fetchServerState() {
        viewModelScope.launch {
            try {
                val response = apiService.getStatus().execute()
                if (response.isSuccessful) {
                    _serverState.value = response.body()?.state?.name ?: "Unknown"
                }
            } catch (e: Exception) {
                _serverState.value = "Error"
            }
        }
    }

    private fun fetchSessions() {
        viewModelScope.launch {
            try {
                val response = apiService.getStatus().execute()
                if (response.isSuccessful) {
                    _sessions.value = response.body()?.sessions ?: emptyList()
                }
            } catch (e: Exception) {
                _sessions.value = emptyList()
            }
        }
    }

    fun closeSession(sessionId: String) {
        viewModelScope.launch {
            try {
                apiService.closeSession(sessionId).execute()
                fetchSessions() // Refresh sessions after closing
            } catch (e: Exception) {
                // Handle error
            }
        }
    }
}

package com.example.remoteclient.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.remoteclient.model.RemoteCredentials
import com.example.remoteclient.network.ApiService
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory

class LoginViewModel : ViewModel() {

    private val _loginState = MutableStateFlow<LoginState>(LoginState.Idle)
    val loginState: StateFlow<LoginState> = _loginState

    private val apiService: ApiService by lazy {
        Retrofit.Builder()
            .baseUrl("http://127.0.0.1:8765")
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(ApiService::class.java)
    }

    fun login(username: String, password: String) {
        viewModelScope.launch {
            try {
                val response = apiService.handshake(RemoteCredentials(username, password)).execute()
                if (response.isSuccessful) {
                    _loginState.value = LoginState.Success
                } else {
                    _loginState.value = LoginState.Error
                }
            } catch (e: Exception) {
                _loginState.value = LoginState.Error
            }
        }
    }

    sealed class LoginState {
        object Idle : LoginState()
        object Success : LoginState()
        object Error : LoginState()
    }
}
